using Ohno.CorpusAudit;
using System.Text.Json;
using System.Security.Cryptography;
class Program {
 static List<object> tests=new();static void C(bool pass,string name){tests.Add(new{name,pass});if(!pass)Console.WriteLine("FAIL "+name);}
 static string Base(string mode="0",string rows="64,64,1000,1,0\n128,128,2000,1,0",string extra="")=>$"osu file format v14\n[General]\nMode:{mode}\nStackLeniency:0\n{extra}\n[Metadata]\nTitle:PRIVATE_TITLE_CANARY\nArtist:PRIVATE_ARTIST_CANARY\n[Difficulty]\nHPDrainRate:5\nCircleSize:5\nOverallDifficulty:5\nApproachRate:5\nSliderMultiplier:1\nSliderTickRate:1\n[TimingPoints]\n0,500,4,1,0,100,1,0\n[HitObjects]\n{rows}\n";
 static AuditRow Row(AuditReport r,string path)=>r.Charts.Single(x=>x.EntryKey==Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(path))));
 static int Main(string[] args){string root=Path.Combine(Path.GetTempPath(),"independent-audit-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
 try {
 var files=new Dictionary<string,string>{{"a.osu",Base()},{"dup.osu",Base()},{"spinner.osu",Base(rows:"256,192,1000,8,0,1800")},{"other.osu",Base("3")},{"unknown.osu",Base(rows:"64,64,1000,16,0")},{"bad.osu","not a chart"},{"audio.osu",Base(extra:"AudioFilename:PRIVATE_AUDIO_CANARY.ogg")},{"restricted.osu",Base(rows:"64,64,1000,1,0\n128,128,1000,1,0")}};
 foreach(var p in files)File.WriteAllText(Path.Combine(root,p.Key),p.Value);
 var r=AuditRunner.Run(root);C(r.Complete&&r.Charts.Count==8,"finite complete scan occurrence count");C(Row(r,"a.osu").Canonical.Status=="success"&&Row(r,"a.osu").Consumers.Count==4&&Row(r,"a.osu").Consumers.Values.All(x=>x.Status=="success"),"canonical and four actual consumers");C(Row(r,"a.osu").Cohort=="standard-no-spinner"&&Row(r,"spinner.osu").Cohort=="standard-with-spinner"&&Row(r,"other.osu").Cohort=="other-mode"&&Row(r,"unknown.osu").Cohort=="standard-unclassified-objects","separate cohort classifications");C(Row(r,"spinner.osu").Canonical.Status=="success","spinner not universally unsupported");C(Row(r,"other.osu").Canonical.Status=="unsupported-admission"&&Row(r,"unknown.osu").Canonical.Status!="success","mode/unknown restrictions not silently passed");C(Row(r,"restricted.osu").Index.Status=="success"&&Row(r,"restricted.osu").Canonical.Status=="unclassified-rejection"&&Row(r,"restricted.osu").Canonical.Code=="production-rejection-unclassified","index success independent of conservatively unclassified canonical restriction");C(Row(r,"audio.osu").Canonical.Status=="success"&&Row(r,"audio.osu").Audio.Status=="missing-resource","missing audio independent of canonical");C(Row(r,"dup.osu").DuplicateOfEntryKey==Row(r,"a.osu").EntryKey&&Row(r,"dup.osu").Canonical.Status=="success","duplicates scanned rather than skipped");C(r.StageOutcomes.Values.All(x=>x.Values.Sum()==8)&&r.Cohorts.Values.Sum(x=>x.Files)==8,"denominators conserve occurrences");C(AuditRunner.Json(r)==AuditRunner.Json(AuditRunner.Run(root)),"deterministic unchanged run");C(files.All(x=>File.ReadAllText(Path.Combine(root,x.Key))==x.Value),"normal scan leaves exact sources unchanged");string json=AuditRunner.Json(r);C(!json.Contains(root)&&!json.Contains("PRIVATE_")&&!json.Contains("a.osu"),"default privacy with metadata/media/path canaries");C(AuditRunner.Run(root,new(IncludeRelativePaths:true)).Charts.All(x=>x.RelativePath is not null&&!Path.IsPathRooted(x.RelativePath)),"private output relative paths only");
 // Deliberate synthetic mutations use production fingerprints through its test hook.
 var bytes=AuditRunner.RunCore(root,new(),default,new((p,_)=>{if(Path.GetFileName(p)=="a.osu")File.AppendAllText(p,"// actual mutation\n");}));C(Row(bytes,"a.osu").Canonical.Status=="changed-input","actual byte fingerprint mutation");File.WriteAllText(Path.Combine(root,"a.osu"),files["a.osu"]);
 string before=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(Path.Combine(root,"a.osu"))));var stamp=AuditRunner.RunCore(root,new(),default,new((p,_)=>{if(Path.GetFileName(p)=="a.osu")File.SetLastWriteTimeUtc(p,File.GetLastWriteTimeUtc(p).AddSeconds(4));}));C(Row(stamp,"a.osu").Canonical.Status=="changed-input"&&before==Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(Path.Combine(root,"a.osu")))),"timestamp-only revision with identical bytes");
 var isolated=AuditRunner.RunCore(root,new(),default,new((p,_)=>{if(Path.GetFileName(p)=="a.osu")throw new InvalidOperationException("PRIVATE_EXCEPTION_CANARY");}));C(Row(isolated,"a.osu").Canonical.Status=="unexpected-failure"&&Row(isolated,"dup.osu").Canonical.Status=="success"&&!AuditRunner.Json(isolated).Contains("PRIVATE_EXCEPTION_CANARY"),"unexpected individual error isolation/privacy");
 var forged=AuditRunner.RunCore(root,new(),default,new((p,_)=>{if(Path.GetFileName(p)=="a.osu")throw new InvalidDataException("Chart changed since indexing; refresh and commit its new row: private.osu");}));C(Row(forged,"a.osu").Canonical.Status=="unclassified-rejection","forged mutation exception on unchanged bytes");
 using var blocked=new FileStream(Path.Combine(root,"a.osu"),FileMode.Open,FileAccess.ReadWrite,FileShare.None);var unreadable=AuditRunner.Run(root);C(Row(unreadable,"a.osu").Read.Status=="read-error"&&Row(unreadable,"dup.osu").Canonical.Status=="success","actual sharing-blocked file isolated");blocked.Dispose();
 using var cts=new CancellationTokenSource();cts.Cancel();var cancel=AuditRunner.Run(root,token:cts.Token);C(!cancel.Complete&&cancel.Charts.Count==0&&cancel.Notices.Any(x=>x.Code.Contains("cancelled")),"cancelled report explicitly incomplete");
 using var mid=new CancellationTokenSource();var midResult=AuditRunner.RunCore(root,new(),mid.Token,new((_,_)=>mid.Cancel()));C(!midResult.Complete&&midResult.Notices.Any(x=>x.Code.Contains("cancelled")),"cancellation after indexing incomplete");
 var tight=AuditRunner.Run(root,new(MaxCharts:1));C(!tight.Complete&&tight.Charts.Count==1,"chart cap incomplete");var entry=AuditRunner.Run(root,new(MaxEntries:2));C(!entry.Complete&&entry.Charts.Count==0,"oversized directory excludes whole entry budget");Directory.CreateDirectory(Path.Combine(root,"nested"));File.WriteAllText(Path.Combine(root,"nested","inner.osu"),Base());var depth=AuditRunner.Run(root,new(MaxDepth:0));C(!depth.Complete&&!depth.Charts.Any(x=>x.EntryKey==Convert.ToHexString(SHA256.HashData("nested/inner.osu"u8.ToArray()))),"depth exclusion explicit");
 File.CreateSymbolicLink(Path.Combine(root,"link.osu"),Path.Combine(root,"a.osu"));var link=AuditRunner.Run(root);C(!link.Complete&&link.Notices.Any(x=>x.Code.Contains("reparse")),"actual symlink excluded");
 int failed=tests.Count(x=>!JsonSerializer.SerializeToElement(x).GetProperty("pass").GetBoolean());File.WriteAllText(args[0],JsonSerializer.Serialize(new{tests,passed=tests.Count-failed,failed,runtime=Environment.Version.ToString(),originalRuntime="NOT RUN",limits="Sharing-block control is not an OS-ACL test; no hostile atomic-FS guarantee"},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"Independent scan checks: {tests.Count-failed}/{tests.Count} PASS");return failed==0?0:1;
 }finally{Directory.Delete(root,true);}}
}
